package net.civeira.phylax.features.access.userconsentpurposes.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IpAddressVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property ip address of user consent purposes ")
  void test_ip_address_v_o_builder() {
    Assertions.assertFalse(IpAddressVO.nullValue().getIpAddress().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(IpAddressVO.tryFrom(null).getIpAddress().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", IpAddressVO.from("one").getIpAddress().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> IpAddressVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", IpAddressVO.from("one").toString());
  }
}
